"import openpyxl
from openpyxl import load_workbook
import shutil

# Copy input to output
shutil.copy('input.xlsx', 'output.xlsx')

wb = load_workbook('output.xlsx')
ws = wb['sheet1']
max_row = ws.max_row

# Read all rows from the sheet
all_rows = []
for r in range(1, max_row + 1):
    all_rows.append({
        'row': r,
        'A': ws.cell(row=r, column=1).value,
        'B': ws.cell(row=r, column=2).value,
        'C': ws.cell(row=r, column=3).value,
        'J': ws.cell(row=r, column=10).value,
    })

# Detect header row (assume first non-empty B row; default row 1)
header_row = 1
for d in all_rows:
    if d['B'] is not None and str(d['B']).strip() != '':
        if d['row'] == 1 or not isinstance(d['B'], (int, float)):
            header_row = d['row']
            break

# Extract helper order from column J (skip header, dedupe preserving first appearance)
helper_order = []
helper_seen = set()
for d in all_rows:
    if d['row'] <= header_row:
        continue
    j_val = d['J']
    if j_val is None:
        continue
    name = str(j_val).strip()
    if name == '':
        continue
    key = name.lower()
    if key not in helper_seen:
        helper_seen.add(key)
        helper_order.append(name)

# Collect unique items from B:C, skipping header, empty cells, and duplicates
items = []
seen_pairs = set()
for d in all_rows:
    if d['row'] <= header_row:
        continue
    b = d['B']
    c = d['C']
    if b is None or str(b).strip() == '':
        continue
    b_str = str(b).strip()
    c_str = str(c).strip() if c is not None else ''
    pair_key = (b_str.lower(), c_str)
    if pair_key in seen_pairs:
        continue
    seen_pairs.add(pair_key)
    items.append({'orig_row': d['row'], 'b': b, 'c': c})

# Sort using helper column order or alphabetically if helper is empty
if helper_order:
    h_idx = {name.lower(): i for i, name in enumerate(helper_order)}

    def sort_key(item):
        b_low = str(item['b']).strip().lower()
        if b_low in h_idx:
            # Items in helper come first, ordered by helper position, then original order
            return (0, h_idx[b_low], item['orig_row'])
        # Items not in helper come after, in original order
        return (1, 0, item['orig_row'])

    items.sort(key=sort_key)
else:
    # Alphabetical sort A-Z by column B
    items.sort(key=lambda x: (str(x['b']).strip().lower(), x['orig_row']))

# Final sort: sort only column H (C values) lowest to highest
def c_sort_key(item):
    c = item['c']
    if c is None or str(c).strip() == '':
        return (1, 0)  # empty/None values go last
    if isinstance(c, (int, float)):
        return (0, float(c))
    try:
        return (0, float(c))
    except (ValueError, TypeError):
        return (0, str(c))

items.sort(key=c_sort_key)

# Write output to F2:H10 (up to 9 rows)
max_output = 9
for i, item in enumerate(items[:max_output]):
    r = 2 + i
    ws.cell(row=r, column=6).value = i + 1          # F: sequence index
    ws.cell(row=r, column=7).value = item['b']        # G: name (from B)
    ws.cell(row=r, column=8).value = item['c']        # H: value (from C), sorted ascending

wb.save('output.xlsx')
print(f"Sorted {min(len(items), max_output)} rows written to F2:H10 in output.xlsx")"
